! ============================================================
! VML FFI 扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 370")   ! 加载动态库
!   call asm("SYSCALL 371")   ! 查找符号
!   call asm("SYSCALL 372")   ! 关闭动态库
!   call asm("SYSCALL 373")   ! 调用原生函数
!   call asm("SYSCALL 374")   ! 获取平台信息
!   call asm("SYSCALL 375")   ! 调用原生函数(浮点参数)
!
! 注意: 仅在 OS 模式 (--mode os, kernel 权限) 下可用
! 错误参数或指针会导致进程崩溃
! ============================================================

! ============================================================
! SYSCALL 370 — DLOpen
! 加载动态库
! 参数: R0 = 库路径字符串地址 (\0 结尾)
! 返回: R0 = 库句柄 (>=1 成功), <0 = 错误
! 错误码: DLL_LOAD_FAILED (-700)
!
! 跨平台路径示例:
!   Windows: "user32.dll"
!   macOS:   "libc.dylib"
!   Linux:   "libc.so.6"
!
! Fortran 使用示例:
!   ! R0 = 库路径的地址
!   call asm("SYSCALL 370")
!   ! 返回: R0 = 库句柄
! ============================================================

! ============================================================
! SYSCALL 371 — DLSym
! 查找动态库中的符号
! 参数:
!   R0 = 库句柄
!   R1 = 符号名称字符串地址 (\0 结尾)
! 返回: R0 = 函数句柄 ID (>=1 成功), <0 = 错误
! 错误码: DLL_INVALID_HANDLE (-704), DLL_SYMBOL_NOT_FOUND (-701)
!
! Fortran 使用示例:
!   ! R0 = 库句柄
!   ! R1 = 函数名 "printf" 的地址
!   call asm("SYSCALL 371")
!   ! 返回: R0 = 函数句柄 ID
! ============================================================

! ============================================================
! SYSCALL 372 — DLClose
! 关闭动态库
! 参数: R0 = 库句柄
! 返回: R0 = 0 成功, <0 = 错误
! 错误码: DLL_INVALID_HANDLE (-704), DLL_UNLOAD_FAILED (-703)
!
! Fortran 使用示例:
!   ! R0 = 库句柄
!   call asm("SYSCALL 372")
! ============================================================

! ============================================================
! SYSCALL 373 — NativeCall
! 调用原生函数 (整数参数和返回值)
! 参数:
!   R0 = 函数句柄 ID (DLSym 返回值)
!   R1 = 参数缓冲区地址 (VML 内存中连续排列的 int32)
!   R2 = 参数个数 (0-12)
!   R3 = 标志位 (bit0: 0=cdecl, 1=stdcall)
! 返回:
!   R0 = 整数返回值
!   F0 = 浮点返回值 (bit1=1 时有效)
! 错误码: DLL_INVALID_HANDLE (-704), DLL_CALL_ERROR (-702)
!
! 限制: 所有参数为 int32
!
! Fortran 使用示例:
!   ! 调用 sin(0.5)
!   ! 1. DLOpen("libm.so.6")
!   ! 2. DLSym(handle, "sin")
!   ! 3. NativeCall(handle, params_buffer, 1, 0)
! ============================================================

! ============================================================
! SYSCALL 374 — GetPlatform
! 获取当前操作系统平台
! 参数: 无
! 返回: R0 = 平台 ID
!   0 = Windows
!   1 = macOS
!   2 = Linux
!   3 = FreeBSD
!  -1 = 未知
!
! Fortran 使用示例:
!   call asm("SYSCALL 374")
!   ! 返回: R0 = 平台 ID
!   ! 可据此选择加载 .dll / .dylib / .so
! ============================================================

! ============================================================
! SYSCALL 375 — NativeCallF
! 调用原生函数 (浮点参数和返回值)
! 参数:
!   R0 = 函数句柄 ID
!   R1 = 浮点参数数组地址 (每参数 4 字节, IEEE 754 float)
!   R2 = 参数个数 (最大 8)
!   R3 = 标志: 0=float 返回值, 1=void 无返回值
! 返回:
!   R0 = float 返回值的位表示 (IEEE 754 bits), void 模式返回 0
! 错误码: DLL_INVALID_HANDLE (-704), MEMORY_OUT_OF_BOUNDS (-5),
!         DLL_CALL_ERROR (-702)
!
! Fortran 使用示例:
!   ! 调用 sinf(0.5) 浮点版本
!   ! 1. DLOpen, 2. DLSym("sinf"), 3. NativeCallF
! ============================================================
